#nullable enable // autogenerated

using MVZ2.GameContent.Projectiles;
using MVZ2.Vanilla.Entities;
using MVZ2.Vanilla.Properties;
using PVZEngine;
using PVZEngine.Buffs;
using PVZEngine.Level;
using PVZEngine.Modifiers;
using UnityEngine;

namespace MVZ2.GameContent.Buffs.Contraptions
{
    [BuffDefinition(VanillaBuffNames.Contraption.soulFurnaceSacrificeInteraction)]
    public class SoulFurnaceSacrificeInteractionBuff : BuffDefinition
    {
        public SoulFurnaceSacrificeInteractionBuff(string nsp, string name) : base(nsp, name)
        {
            AddModifier(new FloatModifier(VanillaEntityProps.DAMAGE, NumberOperator.Multiply, PROP_DAMAGE_MULTIPLIER));
            AddModifier(new NamespaceIDModifier(VanillaEntityProps.PROJECTILE_ID, SetOperator.Set, PROP_PROJECTILE_ID));
            AddModifier(new Vector3Modifier(VanillaEntityProps.SHOT_VELOCITY, NumberOperator.Multiply, PROP_SHOT_VELOCITY_MULTIPLIER));
            AddModifier(new FloatModifier(VanillaEntityProps.ATTACK_SPEED, NumberOperator.Multiply, PROP_ATTACK_SPEED_MULTIPLIER));
        }
        public static void SetDamageMultiplier(Buff buff, float value)
        {
            buff.SetProperty(PROP_DAMAGE_MULTIPLIER, value);
        }
        public static void SetShotVelocityMultiplier(Buff buff, Vector3 value)
        {
            buff.SetProperty(PROP_SHOT_VELOCITY_MULTIPLIER, value);
        }
        public static void SetAttackSpeedMultiplier(Buff buff, float value)
        {
            buff.SetProperty(PROP_ATTACK_SPEED_MULTIPLIER, value);
        }
        public static void SetProjectileID(Buff buff, NamespaceID value)
        {
            buff.SetProperty(PROP_PROJECTILE_ID, value);
        }
        public static readonly VanillaBuffPropertyMeta<float> PROP_DAMAGE_MULTIPLIER = new VanillaBuffPropertyMeta<float>("damageMultiplier", 1);
        public static readonly VanillaBuffPropertyMeta<Vector3> PROP_SHOT_VELOCITY_MULTIPLIER = new VanillaBuffPropertyMeta<Vector3>("shotVelocityMultiplier", Vector3.one);
        public static readonly VanillaBuffPropertyMeta<float> PROP_ATTACK_SPEED_MULTIPLIER = new VanillaBuffPropertyMeta<float>("attackSpeedMultiplier", 1);
        public static readonly VanillaBuffPropertyMeta<NamespaceID> PROP_PROJECTILE_ID = new VanillaBuffPropertyMeta<NamespaceID>("projectileID", VanillaProjectileID.soulfireBall);
    }
}
